import{_ as d,o as r,c as o,a5 as e}from"./chunks/framework.R-FQ1xZ2.js";const p=JSON.parse('{"title":"🔥 面试随身数字卡","description":"","frontmatter":{"title":"🔥 面试随身数字卡","order":7},"headers":[],"relativePath":"interview/cheatsheet.md","filePath":"interview/cheatsheet.md","lastUpdated":null}'),n={name:"interview/cheatsheet.md"};function s(g,t,a,c,h,l){return r(),o("div",null,[...t[0]||(t[0]=[e('<h1 id="🔥-面试随身数字卡" tabindex="-1">🔥 面试随身数字卡 <a class="header-anchor" href="#🔥-面试随身数字卡" aria-label="Permalink to &quot;🔥 面试随身数字卡&quot;">​</a></h1><blockquote><p><strong>用法</strong>：面试前 5 分钟扫一遍。<strong>每一行都带口径和出处</strong>——被追问时不慌。 三条纪律：<strong>报数必带口径</strong> / <strong>不假装跑过</strong> / <strong>配置类开关必须配一个能失败的断言</strong>。</p></blockquote><hr><h2 id="_0-三十秒口径-先背这两句" tabindex="-1">0. 三十秒口径（先背这两句） <a class="header-anchor" href="#_0-三十秒口径-先背这两句" aria-label="Permalink to &quot;0. 三十秒口径（先背这两句）&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">YYHelp（主项目）</p><p>面向电商客服场景的<strong>多轮对话 Agent</strong>：LangGraph 状态图把 <strong>9 类意图</strong>分流到 <strong>5 个出口</strong>，各子流程汇合到主力 Agent 的 ReAct 循环；配套写操作安全（幂等键 + 人工确认）、Milvus 单库双路检索、数据飞轮与<strong>可进 CI 的评测回归门禁</strong>。</p></div><div class="tip custom-block"><p class="custom-block-title">科研文献 RAG（前作）</p><p>面向 AI 领域科研文献的<strong>检索增强问答服务</strong>：混合检索 + 重排序 + 引用溯源 + 拒答机制，并建立了<strong>分层评测集</strong>对检索与生成质量做量化评估。它有一个人工构造不出来的天然负样本集——知识库里只有 USV / MARL 方向文献，问「Transformer 的 KV Cache 显存怎么估算」时<strong>必须拒答</strong>。</p></div><p><strong>前作解决「检索准不准」，本项目解决「多轮对话能不能可靠地把事办完」。</strong></p><hr><h2 id="_1-yyhelp-·-可引用数字" tabindex="-1">1. YYHelp · 可引用数字 <a class="header-anchor" href="#_1-yyhelp-·-可引用数字" aria-label="Permalink to &quot;1. YYHelp · 可引用数字&quot;">​</a></h2><h3 id="_1-1-规模与结构" tabindex="-1">1.1 规模与结构 <a class="header-anchor" href="#_1-1-规模与结构" aria-label="Permalink to &quot;1.1 规模与结构&quot;">​</a></h3><table tabindex="0"><thead><tr><th>数字</th><th>值</th><th>口径 / 出处</th></tr></thead><tbody><tr><td>v2 代码规模</td><td><strong>28 个文件 ≈ 9,957 行</strong> Python</td><td>不含 <code>.venv</code> / <code>__pycache__</code></td></tr><tr><td>最大单文件</td><td><code>graph/supervisor.py</code> <strong>1,827 行</strong></td><td>—</td></tr><tr><td>v1 规模（对照）</td><td><strong>104 个 py 文件 / 21,274 行</strong></td><td>v2 是重写不是重构，<strong>代码量反而少</strong></td></tr><tr><td>v2 state 新字段</td><td><strong>14 个</strong></td><td><code>state_v2.py:399-484</code></td></tr><tr><td>v1 state 字段</td><td><strong>28 个</strong>（9 个带 reducer）</td><td>—</td></tr><tr><td>自检入口总数</td><td>v1 <strong>14</strong> + v2 <strong>16</strong> = <strong>30</strong></td><td><code>test_selftests.py:79/97</code></td></tr><tr><td>专家数 / 工具总数</td><td><strong>5 / 5</strong></td><td><code>experts.py:191</code></td></tr><tr><td>每专家可见工具</td><td><strong>1–3 个</strong></td><td><code>tools_for(spec.name)</code></td></tr><tr><td>可见性探针</td><td><strong>9 条</strong></td><td><code>VISIBILITY_CASES</code>，<code>experts.py:361</code></td></tr><tr><td>全域测试</td><td><strong>36 passed in 79.73s</strong></td><td><code>pytest code/yyhelp_v2 -q</code></td></tr><tr><td>v1 基线测试</td><td><strong>126 passed in 14.50s</strong></td><td>⚠️ <strong>必须带日期</strong>：125 是现状审计日、126 是修 <code>state.py</code> 后</td></tr></tbody></table><h3 id="_1-2-编排参数-可引用常量" tabindex="-1">1.2 编排参数（可引用常量） <a class="header-anchor" href="#_1-2-编排参数-可引用常量" aria-label="Permalink to &quot;1.2 编排参数（可引用常量）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>参数</th><th>值</th><th>出处</th></tr></thead><tbody><tr><td><code>DISPATCH_LIMIT</code>（单轮最多分派次数）</td><td><strong>2</strong></td><td><code>supervisor.py:199</code></td></tr><tr><td><code>REFLECT_MAX_RETRIES</code></td><td><strong>1</strong></td><td><code>state_v2.py:593</code></td></tr><tr><td><code>PLAN_MAX_STEPS</code> / <code>PLAN_MIN_STEPS</code></td><td><strong>3 / 2</strong></td><td><code>plan.py:132/135</code></td></tr><tr><td><code>MODEL_TIMEOUT_S</code></td><td><strong>30.0</strong></td><td>—</td></tr><tr><td><code>BUDGET_WARN_RATIO</code></td><td><strong>0.90</strong></td><td>预算用到 90% 告警</td></tr><tr><td><code>SELFTEST_TIMEOUT_S</code></td><td><strong>60</strong>（从 180 收紧）</td><td>—</td></tr><tr><td>prompt 版本</td><td><code>plan-v2</code> / <code>supervisor-core-v2</code></td><td><code>plan.py:408</code> / <code>supervisor_core.py:203</code></td></tr></tbody></table><h3 id="_1-3-检索与知识库" tabindex="-1">1.3 检索与知识库 <a class="header-anchor" href="#_1-3-检索与知识库" aria-label="Permalink to &quot;1.3 检索与知识库&quot;">​</a></h3><table tabindex="0"><thead><tr><th>数字</th><th>值</th><th>口径 / 出处</th></tr></thead><tbody><tr><td>RRF k</td><td><strong>60</strong></td><td><code>DEFAULT_RRF_K</code>，<code>hybrid.py:85</code> / <code>config.py:176</code></td></tr><tr><td>KB 规模</td><td><strong>163 chunk / 9 doc</strong></td><td>—</td></tr><tr><td>中文分词器</td><td><code>analyzer_params={&quot;tokenizer&quot;:&quot;jieba&quot;}</code></td><td><code>hybrid.py:147-148</code>，<strong>缺则稀疏路静默返回空</strong></td></tr><tr><td>BM25 分数实测</td><td><strong>负值</strong>（如 <strong>−0.6633</strong>）</td><td>BM25 分数无下界，<strong>别拿去和余弦相似度比大小</strong></td></tr><tr><td>RRF 混合路分数</td><td><strong>≈ 0.03</strong> 量级</td><td><code>1/(60+rank)</code> 的量级决定</td></tr><tr><td><code>rank_bm25</code> 对照</td><td>3 万条中文 chunk <strong>仅 15.3 QPS</strong></td><td>自建 BM25 的吞吐天花板</td></tr><tr><td>Milvus 版本门槛</td><td>BM25 需 <strong>2.5.0+</strong>、<code>Function</code> API 需 <strong>2.6.x</strong></td><td>—</td></tr></tbody></table><h3 id="_1-4-a-b-配对评测-最新一轮-120-题-×-2-臂-240-条" tabindex="-1">1.4 A/B 配对评测（<strong>最新一轮：120 题 × 2 臂 = 240 条</strong>） <a class="header-anchor" href="#_1-4-a-b-配对评测-最新一轮-120-题-×-2-臂-240-条" aria-label="Permalink to &quot;1.4 A/B 配对评测（**最新一轮：120 题 × 2 臂 = 240 条**）&quot;">​</a></h3><blockquote><p>⚠️ <strong>这一节在 2026-10-09 被整段替换过。</strong> 旧版是 40 题的数据（40/40 vs 39/40、2.11×、&quot;不证&quot;）——那一版数字<strong>已被证伪</strong>：检索后端从未接入 + 裁判放水。<strong>面试报数一律用下表。</strong></p></blockquote><table tabindex="0"><thead><tr><th>指标</th><th>multi</th><th>single</th><th>结论</th></tr></thead><tbody><tr><td>完成率</td><td><strong>63.3%</strong></td><td><strong>77.5%</strong></td><td>差 <strong>−14.2pp</strong>，CI [−22.0, −6.4]；t p=<strong>0.00053</strong>、Wilcoxon p=<strong>0.0032</strong>，Holm 校正后仍显著 → <strong>REGRESSION</strong></td></tr><tr><td>每问 tokens</td><td><strong>4,708</strong></td><td><strong>5,379</strong></td><td>multi 省 <strong>12.5%</strong>；t p=<strong>0.00034</strong>、Wilcoxon p=<strong>1.8e-6</strong> → <strong>IMPROVEMENT</strong></td></tr><tr><td>每问墙钟</td><td><strong>24.7 s</strong></td><td><strong>17.3 s</strong></td><td><strong>1.43×</strong>；t p≈<strong>0</strong>、Wilcoxon p≈<strong>0</strong> → <strong>REGRESSION</strong></td></tr></tbody></table><p><strong>这三行就是整个项目最值钱的一段话：</strong></p><blockquote><p><strong>120 题配对盲测</strong>：多智能体完成率<strong>低 14.2 个百分点</strong>（p=0.00053）、延迟<strong>高 43%</strong>（p≈0），只在 token 上<strong>省 12.5%</strong>。用 12.5% 的 token 换 14.2pp 完成率和 43% 延迟，<strong>对在线客服是亏的</strong>——所以主链路保持单智能体。</p></blockquote><p><strong>必须主动补的口径</strong>（这一条守住，这段回答就无懈可击）：</p><table tabindex="0"><thead><tr><th>数字</th><th>值</th><th>含义</th></tr></thead><tbody><tr><td>题集来源</td><td><strong>40 题 × 3 个问法变体 = 120 题</strong></td><td>变体由 LLM 改写、<strong>gt 复用原题</strong>；不是为了凑数</td></tr><tr><td>不一致对占比 ψ</td><td><strong>0.208</strong>（旧版 40 题时是 0.025）</td><td>旧版 ψ=0.025 → 有效信息几乎耗尽</td></tr><tr><td>功效分析（ψ=0.208）</td><td><strong>+5pp 需 652 题；+10pp 需 161 题；+20pp 需 39 题</strong></td><td><strong>−14.2pp 在 120 题下可检出；小幅差异仍不可判</strong></td></tr><tr><td><strong>分派鲁棒性</strong></td><td>原题 70% → 变体 <strong>63.3%</strong>（multi）；70% → <strong>77.5%</strong>（single）</td><td>只换问法：<strong>multi 掉 6.7pp、single 升 7.5pp</strong>——差异来自分派，不是模型能力</td></tr><tr><td>四轮链条</td><td>假 <strong>100/97.5</strong> → 修复后 <strong>60/75</strong> → 改进后 <strong>70/70</strong> → 扩样 <strong>63.3/77.5</strong></td><td><strong>数字链本身就是素材</strong>（见 <a href="/learn/interview/architecture-ab.html">架构对比实验</a>）</td></tr><tr><td>三层根因</td><td>检索后端 stub 未接入 / HF_HOME 指向空目录致 dense 静默降级 / 裁判 rubric 放水</td><td>修 rubric 后完成率从 97.5% <strong>掉到 60-75%</strong>——<strong>这才真实</strong></td></tr><tr><td>防复发闸门</td><td>preflight <strong>3 道</strong> + 锚定题 <strong>5 条</strong> + 参考事实注入</td><td>锚定不全对 → 整批标签作废（退出码 2）</td></tr></tbody></table><h3 id="_1-5-评测机制参数" tabindex="-1">1.5 评测机制参数 <a class="header-anchor" href="#_1-5-评测机制参数" aria-label="Permalink to &quot;1.5 评测机制参数&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项</th><th>值</th><th>出处</th></tr></thead><tbody><tr><td>三态退出码</td><td>IMPROVEMENT <strong>0</strong> / REGRESSION <strong>1</strong> / NSC <strong>0</strong> / INCOMPARABLE <strong>2</strong></td><td><code>task_metrics.py:231-234</code></td></tr><tr><td>效应量门槛 <code>min_delta</code></td><td>完成率 <strong>0.05</strong> / tokens <strong>200.0</strong> / 墙钟 <strong>2.0</strong></td><td><code>task_metrics.py:392-396</code></td></tr><tr><td>显著性水平</td><td><code>alpha</code> = <strong>0.05</strong></td><td>同上</td></tr><tr><td>多重比较校正</td><td><strong>Holm</strong></td><td>三个指标同时比较，必须校正</td></tr><tr><td>裁判模型</td><td><code>deepseek-v4-pro</code>，<strong>temperature = 0.0</strong>，<code>response_format={&quot;type&quot;:&quot;json_object&quot;}</code>，回答截 <strong>1500</strong> 字符</td><td>—</td></tr><tr><td>裁判校准</td><td><strong>5 条锚定题</strong>（<code>ANCHOR_ITEMS</code>）+ <strong>参考事实注入</strong>（gt chunk 文本，上限 3000 字）</td><td><code>task_metrics.py</code></td></tr><tr><td>preflight 三闸</td><td>① embedder 维度 = 集合维度 ② 检索后端 = semantic ③ 端到端 smoke</td><td><code>run_ab.py::_preflight_embedder_dim</code></td></tr><tr><td>eval set（主）</td><td><strong>120 题</strong>：40 题 × 3 变体（<code>questions_v3_x3.jsonl</code>）</td><td><code>data/yyhelp/eval/</code></td></tr><tr><td>eval set（原集）</td><td>40 题：single_hop 12 / synonym 8 / unanswerable 8 / multi_hop 6 / exact_term 6</td><td><code>questions_v3_cross.jsonl</code></td></tr><tr><td>检索性能</td><td>encode 稳态 <strong>0.03 s/条</strong>（首次 12s 是模型加载）</td><td><code>bench_encode.py</code> 实测</td></tr><tr><td>服务压测</td><td>6 并发 / 18 请求 → p50 <strong>74.8 s</strong>、p95 <strong>120.7 s</strong>；拒答路径 <strong>~1 s 零 token</strong></td><td><code>loadtest_b2.py</code></td></tr><tr><td>LLM 轮次</td><td>single <strong>1.85 次/问</strong>、multi <strong>3.95 次/问</strong>；<strong>瓶颈在 LLM 调用链</strong></td><td><code>analyze_calls.py</code></td></tr><tr><td>模型对比</td><td>flash vs v4-pro 同 10 题：p50 <strong>33.4s → 20.2s（−40%）</strong></td><td><code>bench_model.py</code></td></tr></tbody></table><h3 id="_1-6-长期记忆-有反直觉设计-主动讲" tabindex="-1">1.6 长期记忆（有反直觉设计，<strong>主动讲</strong>） <a class="header-anchor" href="#_1-6-长期记忆-有反直觉设计-主动讲" aria-label="Permalink to &quot;1.6 长期记忆（有反直觉设计，**主动讲**）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项</th><th>值</th></tr></thead><tbody><tr><td><code>RECALL_POLICY</code></td><td><strong><code>&quot;state_only&quot;</code></strong> —— 召回结果<strong>写进 state，但不拼进 prompt</strong>（<code>longterm.py:810</code>）</td></tr><tr><td>写入门槛</td><td>preference <strong>0.60</strong> / fact <strong>0.75</strong> / solution <strong>0.80</strong> / correction <strong>0.85</strong>；未知 kind 0.85</td></tr><tr><td>半衰期（天）</td><td>preference <strong>90</strong> / solution <strong>180</strong> / fact 与 correction <strong>None（不衰减）</strong></td></tr><tr><td><code>RECALL_TOP_K</code> / <code>MIN_CONFIDENCE</code> / <code>MIN_SCORE</code> / <code>DECAY_FLOOR</code></td><td><strong>3 / 0.55 / 0.25 / 0.30</strong></td></tr><tr><td>打分权重</td><td><code>W_SIM 0.55 + W_OVERLAP 0.25 + W_DECAY 0.20 = 1</code>；<code>HASH_DIM = 64</code></td></tr><tr><td>集合隔离</td><td>记忆 <code>yyhelp_memory_v1</code>、知识库 <code>yyhelp_kb_v1</code>，<strong>物理隔离</strong></td></tr></tbody></table><h3 id="_1-7-mcp" tabindex="-1">1.7 MCP <a class="header-anchor" href="#_1-7-mcp" aria-label="Permalink to &quot;1.7 MCP&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项</th><th>值</th></tr></thead><tbody><tr><td>版本</td><td><code>mcp&gt;=1.28,&lt;2</code>，<strong>实装 1.30.0</strong></td></tr><tr><td>暴露的工具</td><td><strong>2 个只读</strong>：<code>search_kb</code>、<code>query_order</code>（<code>client.py:145-263</code>）</td></tr><tr><td><strong>明确禁止暴露</strong></td><td><strong>3 个</strong>：<code>create_ticket</code> / <code>query_refund_policy</code> / <code>query_logistics</code></td></tr><tr><td>stderr 噪声</td><td>一次 streamable-http 往返 <strong>17 行</strong>；集中治理 <strong>12 个 logger</strong>，静音级别取 <code>logging.WARNING</code></td></tr><tr><td>超时</td><td><code>READY_TIMEOUT_S = 15.0</code> / <code>CALL_TIMEOUT_S = 20.0</code></td></tr><tr><td>MCP 自检耗时</td><td><strong>2.84 s</strong></td></tr></tbody></table><p><strong>面试口径</strong>：「我们只把<strong>只读</strong>工具放上 MCP，三个写操作/敏感查询明确不暴露。理由是 MCP server 是独立进程，<strong>权限边界不由主图控制</strong>——一旦暴露，写操作就失去了幂等键与人工确认这两道闸。<strong>MCP 的价值是解耦工具实现，不是绕过我的安全设计。</strong>」</p><h3 id="_1-8-并发实验-gil-那一课" tabindex="-1">1.8 并发实验（GIL 那一课） <a class="header-anchor" href="#_1-8-并发实验-gil-那一课" aria-label="Permalink to &quot;1.8 并发实验（GIL 那一课）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项</th><th>值</th></tr></thead><tbody><tr><td>实验规模</td><td><code>CONCURRENCY = 8</code> / <code>TRIALS = 3</code>（取中位数）</td></tr><tr><td>负载参数</td><td><code>CPU_ITERATIONS = 3_000_000</code>（<strong>用迭代次数不用秒数</strong>）/ <code>NATIVE_BYTES = 52_000_000</code> / <code>IO_SLEEP_MS = 120.0</code></td></tr><tr><td>加速比判据</td><td><code>&lt; 1.2</code> 无明显收益 / <code>≥1.2 且 &lt; concurrency/2</code> 部分收益 / <code>≥ concurrency/2</code> 接近线性</td></tr><tr><td>⭐ <strong>块在函数内构造</strong></td><td><strong>1.02×（假结论）</strong></td></tr><tr><td>⭐ <strong>块在模块级预建</strong></td><td><strong>6.41×（真结论）</strong></td></tr><tr><td>对照组 <code>zlib.decompress</code></td><td>同为释放 GIL 但需分配 52 MB → 只有 <strong>2.13×</strong></td></tr></tbody></table><p><strong>面试口径</strong>：「基准测试的<strong>脚手架本身会污染结论</strong>。第一版把瓶颈块写在函数里，构造开销占了主导，测出来 1.02× 像是『GIL 锁死了并行』；把块提到模块级预建后是 6.41×。所以<strong>任何性能结论都要先怀疑测量方式</strong>。」</p><h3 id="_1-9-服务与部署" tabindex="-1">1.9 服务与部署 <a class="header-anchor" href="#_1-9-服务与部署" aria-label="Permalink to &quot;1.9 服务与部署&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项</th><th>值</th></tr></thead><tbody><tr><td>限流</td><td><strong>60 次/分钟</strong>（<code>YYHELP_RATE_LIMIT_PER_MIN</code>）</td></tr><tr><td>API 端口</td><td><strong>8080</strong>；端点 <strong>3 个</strong>：<code>GET /health</code>、<code>POST /ask</code>、<code>POST /ask/stream</code></td></tr><tr><td>FastAPI</td><td><code>FastAPI(title=&quot;YYHelp API&quot;, version=&quot;0.3.0&quot;)</code></td></tr><tr><td>容器</td><td>基础镜像 <code>python:3.12-slim</code>；运行用户 <code>yyhelp</code> uid <strong>10001</strong>，<strong>非 root</strong></td></tr><tr><td>MySQL</td><td><strong>8.4.11</strong>，宿主端口 <strong>3307</strong>，<code>utf8mb4</code> + 排序规则 <code>0900</code></td></tr><tr><td>etcd / MinIO</td><td>etcd <strong>v3.5.25</strong>（4 GiB 配额）/ MinIO 用 digest 钉版本</td></tr><tr><td>模型实测速度</td><td><code>deepseek-v4-pro</code> <strong>7.76 s/次</strong>；<code>deepseek-flash</code> 在实测中<strong>挂起</strong></td></tr></tbody></table><h3 id="_1-10-环境版本-被问「你用什么版本」时用" tabindex="-1">1.10 环境版本（被问「你用什么版本」时用） <a class="header-anchor" href="#_1-10-环境版本-被问「你用什么版本」时用" aria-label="Permalink to &quot;1.10 环境版本（被问「你用什么版本」时用）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>组件</th><th>版本</th></tr></thead><tbody><tr><td>Python</td><td><strong>3.12.7</strong></td></tr><tr><td>langgraph</td><td><strong>1.2.12</strong></td></tr><tr><td>langgraph-checkpoint / -sqlite</td><td><strong>4.2.0 / 3.1.1</strong></td></tr><tr><td>pymilvus / milvus-lite</td><td><strong>3.0.2 / 3.2.1</strong></td></tr><tr><td>mcp</td><td><strong>1.30.0</strong></td></tr><tr><td>pydantic</td><td><strong>2.13.5</strong></td></tr><tr><td>fastapi / starlette</td><td><strong>0.141.1 / 1.7.0</strong>（基线<strong>未被 mcp 污染</strong>）</td></tr></tbody></table><hr><h2 id="_2-rag-·-可引用数字" tabindex="-1">2. RAG · 可引用数字 <a class="header-anchor" href="#_2-rag-·-可引用数字" aria-label="Permalink to &quot;2. RAG · 可引用数字&quot;">​</a></h2><h3 id="_2-1-语料与索引" tabindex="-1">2.1 语料与索引 <a class="header-anchor" href="#_2-1-语料与索引" aria-label="Permalink to &quot;2.1 语料与索引&quot;">​</a></h3><table tabindex="0"><thead><tr><th>数字</th><th>值</th><th>口径</th></tr></thead><tbody><tr><td>✅ <strong>有效文献 / 有效切片</strong></td><td><strong>55 篇 / 5325 块</strong></td><td><code>eval/report.md:129</code>，<strong>当前真值</strong></td></tr><tr><td>原始导入</td><td>59 篇</td><td>其中 3 篇扫描件、1 篇重复，<strong>已剔除</strong></td></tr><tr><td>向量维度</td><td><strong>1024</strong>（bge-m3）</td><td><code>config.py:152</code></td></tr><tr><td>真实切片平均长度</td><td><strong>763 字符</strong>（最长 1132）</td><td><code>exp10</code> docstring</td></tr><tr><td>索引产物大小</td><td><code>chunks.jsonl</code> 5.8 MB / <code>index.faiss</code> <strong>21.8 MB</strong> / <code>bm25.pkl</code> 5.5 MB</td><td>文件系统</td></tr><tr><td>索引吞吐</td><td><strong>2.92 块/秒</strong>（真实）</td><td><code>exp10</code>、<code>exp33</code>；⚠️ 旧错误值 23.41 块/秒</td></tr><tr><td>Flat 检索性能</td><td><strong>毫秒级</strong>（52 万块量级）</td><td><code>exp31</code> docstring</td></tr></tbody></table><h3 id="_2-2-关键配置-源码事实" tabindex="-1">2.2 关键配置（源码事实） <a class="header-anchor" href="#_2-2-关键配置-源码事实" aria-label="Permalink to &quot;2.2 关键配置（源码事实）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>参数</th><th>值</th><th>出处</th></tr></thead><tbody><tr><td><code>max_chars</code>（512 档 / 1024 档）</td><td><strong>1024 / 2048 字符</strong></td><td><code>config.py:156-159</code> ⚠️ <strong>键名是 token 名义值，不是字符数</strong></td></tr><tr><td><code>overlap_chars</code></td><td><strong>153 / 307 字符</strong>（15%）</td><td>同上</td></tr><tr><td><code>DENSE_TOP_K</code> / <code>SPARSE_TOP_K</code> / <code>FUSED_TOP_K</code></td><td><strong>20 / 20 / 20</strong></td><td><code>config.py:163-166</code></td></tr><tr><td><code>RERANK_TOP_N</code></td><td><strong>5</strong></td><td><code>config.py:167</code></td></tr><tr><td><code>RRF_K</code></td><td><strong>60</strong></td><td><code>config.py:165</code></td></tr><tr><td><code>SPARSE_OVERLAP_K</code> / <code>SPARSE_OVERLAP_MIN</code></td><td><strong>20 / 2</strong></td><td><code>config.py:181-182</code></td></tr><tr><td><code>REFUSE_THRESHOLD</code></td><td><strong>0.30</strong></td><td><code>config.py:170</code></td></tr><tr><td>精排 <code>max_length</code></td><td><strong>512</strong></td><td><code>retrieve.py:117</code></td></tr><tr><td>LLM 温度 / 超时 / 重试</td><td><strong>0.1 / 60 s / 3</strong></td><td><code>config.py:190,203,209</code></td></tr><tr><td>重试退避</td><td><code>min(0.8·2^(n−1), 8.0)</code> + 抖动 ≤ 25%</td><td><code>config.py:210-211</code></td></tr><tr><td>限流 / 并发 / 请求超时</td><td><strong>30 次/分 / 2 / 120 s</strong></td><td><code>service.py:47-59</code></td></tr><tr><td>告警冷却 / 错误率阈值 / 最少样本</td><td><strong>300 s / 0.2 / 10</strong></td><td><code>guard.py:23-32</code></td></tr><tr><td>术语表</td><td><strong>57 条</strong></td><td><code>glossary.py:25-79</code></td></tr></tbody></table><h3 id="_2-3-⭐-检索三档对照-这一张表是-rag-项目的心脏" tabindex="-1">2.3 ⭐ 检索三档对照（<strong>这一张表是 RAG 项目的心脏</strong>） <a class="header-anchor" href="#_2-3-⭐-检索三档对照-这一张表是-rag-项目的心脏" aria-label="Permalink to &quot;2.3 ⭐ 检索三档对照（**这一张表是 RAG 项目的心脏**）&quot;">​</a></h3><p><strong>统一口径：124 题 / gt 206 块 / 密度 1.66 块每题</strong>（<code>eval/report.md:41-43</code>）</p><table tabindex="0"><thead><tr><th>方案</th><th>R@5</th><th>R@10</th><th>MRR</th></tr></thead><tbody><tr><td>① 纯向量</td><td><strong>64.4%</strong></td><td>73.7%</td><td>0.577</td></tr><tr><td>② 混合检索（无精排）</td><td><strong>59.1%</strong></td><td>69.2%</td><td>0.502</td></tr><tr><td>③ 混合 + 精排</td><td><strong>71.8%</strong></td><td><strong>77.4%</strong></td><td><strong>0.714</strong></td></tr></tbody></table><p><strong>必须主动讲的一句</strong>：<strong>② 比 ① 还差。</strong> 混合检索<strong>不天然更好</strong>——加进来的是噪声还是互补信息，取决于语料。<strong>是精排把混合检索救回来的</strong>（59.1% → 71.8%，+12.7pp）。</p><h3 id="_2-4-拒答-双层-与护栏" tabindex="-1">2.4 拒答（双层）与护栏 <a class="header-anchor" href="#_2-4-拒答-双层-与护栏" aria-label="Permalink to &quot;2.4 拒答（双层）与护栏&quot;">​</a></h3><table tabindex="0"><thead><tr><th>指标</th><th>值</th><th>口径</th></tr></thead><tbody><tr><td>拒答准确率 / 误拒率 / 漏拒</td><td><strong>100.0% / 7.3% / 0</strong></td><td>124 题同口径</td></tr><tr><td>top1 分数（<strong>可回答</strong> n=124）</td><td>min <strong>0.0411</strong> / 中位 <strong>0.9617</strong> / max <strong>0.9999</strong></td><td>阈值 <strong>0.30</strong></td></tr><tr><td>top1 分数（<strong>不可回答</strong> n=6）</td><td>min <strong>0.0018</strong> / 中位 <strong>0.0127</strong> / max <strong>0.2502</strong></td><td>同上</td></tr><tr><td>仅阈值层误拒率</td><td><strong>1.6%</strong></td><td><code>eval/report.md:135</code></td></tr><tr><td>阈值层 + prompt 层 误拒率</td><td><strong>6.5%</strong>（另一次 5.6%）</td><td>同上</td></tr></tbody></table><p><strong>这两层分开测的意义</strong>：程序层拒答<strong>零成本</strong>（不调 LLM），模型层自报 <code>insufficient</code> 是兜底。<strong>合起来测就只能看到一个 6.5%，看不出该优化哪一层。</strong></p><h3 id="_2-5-分题型-分来源拆解-报-r-5-时必须能拆" tabindex="-1">2.5 分题型 / 分来源拆解（<strong>报 R@5 时必须能拆</strong>） <a class="header-anchor" href="#_2-5-分题型-分来源拆解-报-r-5-时必须能拆" aria-label="Permalink to &quot;2.5 分题型 / 分来源拆解（**报 R@5 时必须能拆**）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>拆法</th><th>值</th></tr></thead><tbody><tr><td>新 100 题 vs 旧 30 题（③ R@5）</td><td><strong>74.2% vs 61.8%</strong></td></tr><tr><td>single_hop vs multi_hop（③ R@5）</td><td><strong>79.2% vs 53.7%</strong></td></tr><tr><td>跨语种 BM25：raw / +术语表 / +LLM 翻译</td><td><strong>8.3% / 29.2% / 70.8%</strong>（R@5）</td></tr><tr><td>术语表对 ③ 的增益</td><td>R@5 73.2% → <strong>74.6%</strong>、R@10 73.2% → <strong>79.0%</strong>、MRR 0.696 → <strong>0.702</strong>（23 题）</td></tr></tbody></table><p><strong>面试口径</strong>：「整体 R@5 是 71.8%，但<strong>这个数单独报没有意义</strong>。拆开看：单跳 79.2%、多跳只有 53.7%。多跳是我们明确知道的最短板，<code>known_issues</code> 里挂着 3 条未达标题（S08 / S13 / M06）。」</p><h3 id="_2-6-延迟分解-「优化-llm」是错的方向" tabindex="-1">2.6 延迟分解（<strong>「优化 LLM」是错的方向</strong>） <a class="header-anchor" href="#_2-6-延迟分解-「优化-llm」是错的方向" aria-label="Permalink to &quot;2.6 延迟分解（**「优化 LLM」是错的方向**）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>指标</th><th>值</th><th>来源</th></tr></thead><tbody><tr><td>检索 P50 / P90 / P99</td><td><strong>14.47 / 18.44 / 30.74 s</strong></td><td><code>output/latency_report.md</code>（30 题）</td></tr><tr><td>LLM 生成 P50 / P90 / P99</td><td><strong>1.26 / 1.87 / 2.82 s</strong></td><td>同上</td></tr><tr><td>端到端 P50 / P90 / P99</td><td><strong>15.66 / 19.58 / 32.26 s</strong></td><td>同上</td></tr><tr><td>流式 TTFT</td><td><strong>14.90 / 10.00 / 14.86 s</strong>（≈ 检索耗时）</td><td><code>output/05-面试准备-RAG数据.md:84</code></td></tr><tr><td>⭐ 单次精排（20 对，CPU）</td><td><strong>约 8.5 s</strong></td><td><code>exp31</code>、<code>generate.py</code> 注释</td></tr><tr><td>冷启动</td><td><strong>67.3 s</strong></td><td>同上</td></tr></tbody></table><p><strong>面试口径</strong>：「首字延迟<strong>约等于检索耗时</strong>，而检索里最大的那块是 <strong>CPU 精排 20 对约 8.5 秒</strong>，LLM 生成 P50 只有 <strong>1.26 秒</strong>。所以<strong>去优化 LLM 是错的方向</strong>——要动的是精排：换更小的 reranker、上 GPU、或者把 20 对砍到 10 对。」</p><h3 id="_2-7-评测集与标注工程" tabindex="-1">2.7 评测集与标注工程 <a class="header-anchor" href="#_2-7-评测集与标注工程" aria-label="Permalink to &quot;2.7 评测集与标注工程&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项</th><th>值</th></tr></thead><tbody><tr><td>题集规模</td><td><strong>130</strong>（可回答 124 + 不可回答 6）</td></tr><tr><td>gt 块总数 / 密度</td><td><strong>206 块 / 1.66 块每题</strong></td></tr><tr><td>题型分布</td><td>multi_hop <strong>36</strong> / single_hop <strong>88</strong></td></tr><tr><td>主题覆盖</td><td>9 类，其中 <strong>6 类为旧题未碰过</strong></td></tr><tr><td>新增题</td><td>N001–N100（<strong>100 道，读语料块出题</strong>）</td></tr><tr><td>已知未达标题</td><td><strong>3 条</strong>（S08 / S13 / M06，<code>known_issues.json</code>）</td></tr><tr><td>回归用例集</td><td><code>cases.jsonl</code> 5536 B</td></tr><tr><td>标注工程规模</td><td><code>gt_diff.md</code> 36 KB、<code>quote_worksheet.md</code> <strong>82 KB</strong>、<code>human_review</code> 19.8 KB、<code>negatives_review</code> 20.5 KB</td></tr><tr><td>全量验收</td><td><strong>PASS 17 / FAIL 0</strong></td></tr><tr><td>离线服务测试 / 配额冒烟</td><td><strong>24 项 / 14 项</strong></td></tr></tbody></table><h3 id="_2-8-成本" tabindex="-1">2.8 成本 <a class="header-anchor" href="#_2-8-成本" aria-label="Permalink to &quot;2.8 成本&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项</th><th>值</th></tr></thead><tbody><tr><td>单次问答 token</td><td><strong>1290 prompt + 36 completion</strong></td></tr><tr><td>单次费用</td><td><strong>$4.6e-05</strong></td></tr><tr><td>200 次/天</td><td>≈ <strong>$0.01/天</strong></td></tr><tr><td>1 万次/天</td><td><strong>$0.46/天</strong></td></tr><tr><td><code>deepseek-flash</code> 峰时价</td><td>in_miss <strong>0.30</strong> / in_hit <strong>0.006</strong> / out <strong>1.20</strong>（美元/百万 token）</td></tr><tr><td><code>deepseek-v4-pro</code> 峰时价</td><td><strong>1.32 / 0.044 / 3.96</strong></td></tr><tr><td>定价取数日期</td><td><strong>2026-09-28</strong>（<code>obs.py:41</code>）</td></tr></tbody></table><hr><h2 id="_3-🚫-黑名单-这些数不要报" tabindex="-1">3. 🚫 黑名单：这些数<strong>不要报</strong> <a class="header-anchor" href="#_3-🚫-黑名单-这些数不要报" aria-label="Permalink to &quot;3. 🚫 黑名单：这些数**不要报**&quot;">​</a></h2><table tabindex="0"><thead><tr><th>数字</th><th>为什么不能报</th><th>该怎么说</th></tr></thead><tbody><tr><td>「知识库 <strong>5 篇 / 523 块</strong>」</td><td>16 份 <code>_abl_*.md</code> 里的<strong>过期模板文本</strong>，被一路照抄。<strong>引用会当场露馅</strong></td><td>「那是早期 5 篇小语料的消融实验规模，不是当前库」</td></tr><tr><td>「<strong>5470 块 / 56 篇</strong>」</td><td><code>out/MANIFEST.json</code> 的<strong>去重前中间态</strong>，清单文件已过期</td><td>「那是去重前的数。<strong>清单和实际产物会漂移</strong>，所以评测报告现在强制带口径和日期」</td></tr><tr><td>答案准确率 <strong>65.2% / 91.3%</strong></td><td><strong>旧 30 题口径</strong>、LLM 裁判<strong>未人工校准</strong>，与当前 130 题报告<strong>不是同一批次</strong></td><td>「那是旧 30 题的宽松/严格口径，裁判没校准过，我不拿它当结论」</td></tr><tr><td>机器 gt 报告的任何数字（如 ①83.2% ②82.2% ③100%）</td><td><strong>gt 有循环依赖</strong>（候选窗口只取 <code>retrieve()[:5]</code>），<strong>报告自己顶部就写着「🚫 不可作为结论」</strong></td><td>「那个数我们自己标了不可用，因为它有循环依赖」</td></tr><tr><td>压测分位数（P50 7.5→45.8 s）</td><td>每档只有 <strong>3–8 个请求</strong></td><td>「<strong>结构性结论可用</strong>（并发上去延迟涨），<strong>不能写进 SLA</strong>」</td></tr><tr><td>「首个请求等 48 秒」</td><td>只有 <code>service.py</code> <strong>源码注释自述</strong>，<strong>没见到原始日志</strong></td><td>「这个数来自源码注释的自述实测，我没有原始日志」</td></tr><tr><td><code>exp04 / 11 / 12 / 24 / 25 / 26 / 28 / 32 / 34</code> 的输出数字</td><td><strong>脚本输出未读到</strong>，只有 docstring 写的目的与方法</td><td>「那几个实验我只留了脚本，输出没归档」</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">一张万能挡箭牌（但<strong>不能滥用</strong>）</p><p>「<strong>这个数我没实测，我只写了方法和验证命令。</strong>」——<strong>能说这句话的人比能报漂亮数字的人可信得多。</strong> 但如果每个数都这么说，就变成什么都没做。</p></div><hr><h2 id="_4-数字被质疑时-三句话" tabindex="-1">4. 数字被质疑时，三句话 <a class="header-anchor" href="#_4-数字被质疑时-三句话" aria-label="Permalink to &quot;4. 数字被质疑时，三句话&quot;">​</a></h2><ol><li><strong>「这个数的口径是：N 题 / gt 版本 X / 密度 Y 块每题。」</strong> —— 先把标尺摆出来。</li><li><strong>「它只能支持 X 这个结论，不支持 Y。」</strong> —— 主动划边界。</li><li><strong>「这个数我是在 <code>文件:行号</code> 里核出来的。」</strong> —— 给溯源。</li></ol><hr><h2 id="_5-两个项目「最值钱的五条」——被问「你最有成就感的是什么」时挑一条讲" tabindex="-1">5. 两个项目「最值钱的五条」——被问「你最有成就感的是什么」时挑一条讲 <a class="header-anchor" href="#_5-两个项目「最值钱的五条」——被问「你最有成就感的是什么」时挑一条讲" aria-label="Permalink to &quot;5. 两个项目「最值钱的五条」——被问「你最有成就感的是什么」时挑一条讲&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>讲什么</th><th>为什么值钱</th></tr></thead><tbody><tr><td>1</td><td><strong>四轮实验把&quot;漂亮的假数字&quot;查成&quot;统计显著的结论&quot;</strong></td><td>第一版是 <strong>100/97.5 的假数据</strong>（检索替身 + 裁判放水）→ 修三层根因后 <strong>60/75</strong> → 改进后 <strong>70/70</strong> → 扩样 120 题 <strong>63.3/77.5（−14.2pp，p=0.00053）</strong>。<strong>能讲清&quot;数字变好看先怀疑链路、别先怀疑模型&quot;的人极少</strong></td></tr><tr><td>2</td><td><strong><code>R@10 == R@5</code> 是标注窗口造出来的假象</strong></td><td>一个<strong>自己发现自己的评测有构造性偏差</strong>的故事。修好后立刻暴露「不做精排时 R@10 比 R@5 高 11–14pp」</td></tr><tr><td>3</td><td><strong><code>SPARSE_MODE=overlap</code> 的自检失效机制</strong></td><td>扩库后混合检索 R@5 从 <strong>64.5% 崩到 29.2%</strong>，根因是中文查询的 BM25 top-20 <strong>全部来自那 2 篇中文文献</strong>——<strong>「同语言 ≠ 同主题」</strong></td></tr><tr><td>4</td><td><strong>两个静默故障</strong></td><td>Milvus 默认 analyzer 导致<strong>中文 BM25 返回空但不报错</strong>；<code>add_conditional_edges</code> 的 <code>path_map</code> 传错 → <code>KeyError: &#39;agent_memory&#39;</code>，<strong>「能 import、能编译、一跑就崩，纯函数单测测不出」</strong></td></tr><tr><td>5</td><td><strong>「写下 ≠ 执行」</strong></td><td>v1 有 <strong>11 个 selftest 从未被 pytest 执行</strong>，<code>state.py</code> 的缺陷因此「红了不知道多久」</td></tr></tbody></table><hr><h2 id="_6-反过来问面试官-面试尾声用-挑-2-个" tabindex="-1">6. 反过来问面试官（面试尾声用，挑 2 个） <a class="header-anchor" href="#_6-反过来问面试官-面试尾声用-挑-2-个" aria-label="Permalink to &quot;6. 反过来问面试官（面试尾声用，挑 2 个）&quot;">​</a></h2><ul><li>团队现在的 Agent 产品，<strong>评测是怎么做的</strong>？有没有能进 CI 的门禁？</li><li>多智能体在这个团队是<strong>默认方案还是被验证过的方案</strong>？</li><li>从 0 到 1 做一个新 Agent 应用，<strong>你们最卡的一环是模型能力、工程基建，还是评测与数据闭环</strong>？</li><li>这个岗位入职后前三个月，<strong>最希望我独立交付的一件事</strong>是什么？</li></ul><hr><h2 id="_7-五条地基纪律-忘了所有数字也要记住这五条" tabindex="-1">7. 五条地基纪律（忘了所有数字也要记住这五条） <a class="header-anchor" href="#_7-五条地基纪律-忘了所有数字也要记住这五条" aria-label="Permalink to &quot;7. 五条地基纪律（忘了所有数字也要记住这五条）&quot;">​</a></h2><ol><li><strong>报数必带口径。</strong> recall@5 要说明 macro/micro、k、是否含精排、分母定义、gt 来源。</li><li><strong>不假装跑过。</strong> 没跑的写「未执行验证」并给出验收命令。</li><li><strong>配置类开关必须配一个「能失败的断言」。</strong> 只验「没报错」等于没验——<strong>中文分词器就是活例子</strong>。</li><li><strong>装配错误必须靠运行图来验</strong>，不能靠读代码。</li><li><strong>基准测试先怀疑测量方式</strong>，再怀疑被测对象（1.02× vs 6.41×）。</li></ol><hr><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li><a href="/learn/interview/">面试准备总览</a> —— 48 小时止血阅读顺序</li><li><a href="/learn/interview/project-grilling.html">项目深挖预演</a> —— 十条追问链</li><li><a href="/learn/projects/yyhelp/">YYHelp 项目地图</a> ｜ <a href="/learn/projects/rag/">科研文献 RAG 项目地图</a></li><li><a href="/learn/roadmap/progress.html">进度看板</a> —— 投递台账与错题本</li></ul>',78)])])}const b=d(n,[["render",s]]);export{p as __pageData,b as default};
